import argparse,json,html
from pathlib import Path
import pandas as pd

p=argparse.ArgumentParser();p.add_argument('--out',type=Path,required=True);p.add_argument('--inputs',type=Path,required=True);a=p.parse_args();out=a.out;cfg=json.loads(a.inputs.read_text());base=a.inputs.parent
h=pd.read_csv(out/'GENE_CLASSIFICATION.tsv',sep='\t');m=pd.read_parquet(out/'04_mobility/MOBILITY_UNIFIED248.parquet');m=m[m.length_kb.eq(0)]
hitpath=out/'05_alignment/POSITIVE_REFERENCE_HITS.tsv'
if not hitpath.exists():hitpath=out/'05_alignment/PREDICTED_TARGET_REFERENCE_HITS.tsv'
hits=pd.read_csv(hitpath,sep='\t',keep_default_na=False) if hitpath.exists() else pd.DataFrame()
target_ids=set(h.loc[h.final_class.isin(['ARG','MRG','MGE']),'protein_id'])
if len(hits):hits=hits[hits.protein_id.isin(target_ids)].copy()
(out/'05_alignment').mkdir(exist_ok=True)
hits.to_csv(out/'05_alignment/PREDICTED_TARGET_REFERENCE_HITS.tsv',sep='\t',index=False)
def clean(df):return json.loads(df.to_json(orient='records'))
cases=pd.read_csv(base/cfg['case_table'],sep='\t') if 'case_table' in cfg else pd.DataFrame()
genes=pd.read_csv(base/cfg['case_genes'],sep='\t') if 'case_genes' in cfg else pd.DataFrame()
rows=clean(h);mob={r['host_protein_id']:r for r in clean(m)};al=clean(hits);export=[]
for r in rows:
    r['mobility']=mob.get(r['protein_id'])
    r['alignment_eligible']=r['protein_id'] in target_ids
    r['hits']=[x for x in al if x['protein_id']==r['protein_id']]
    best=r['hits'][0] if r['hits'] else {}
    r['strict_hits']=sum(bool(x['strict_support']) for x in r['hits'])
    r['strict_reference_classes']=sorted({x['reference_class'] for x in r['hits'] if x['strict_support']})
    r['reference_review']=bool(r['strict_reference_classes'] and (r['final_class'] not in r['strict_reference_classes'] or len(r['strict_reference_classes'])>1))
    r['reference_review_reason']=('Model class: '+r['final_class']+'; strict reference classes: '+' / '.join(r['strict_reference_classes'])+'. ' if r['final_class'] not in r['strict_reference_classes'] else 'Strict matches span '+' / '.join(r['strict_reference_classes'])+' reference classes; review the overlap.') if r['reference_review'] else ''
    r['best']=best
    c=cases[cases.cargo_gene_id.eq(r['protein_id'])] if len(cases) else pd.DataFrame()
    r['case']={k:v for k,v in clean(c)[0].items() if k in ['case_id','reference_start1','reference_end1','nearest_mge_gap_bp']} if len(c) else None;r['neighbors']=[]
    if len(c):
        g=genes[genes.case_id.eq(c.iloc[0].case_id)].sort_values('start1').reset_index(drop=True)
        ix=int(g.index[g.gene_id.eq(r['protein_id'])][0]);r['neighbors']=clean(g.iloc[max(0,ix-10):ix+11])
    export.append({'protein_id':r['protein_id'],'model_class':r['final_class'],'model_fine_labels':r.get('fine_predicted_labels'),'target_probability':r['gate_score'],'mobility_association_score':(r['mobility'] or {}).get('unified248_score'),'mobility_threshold':(r['mobility'] or {}).get('unified248_threshold'),'best_reference_id':best.get('reference_id'),'best_reference_class':best.get('reference_class'),'best_reference_name':best.get('reference_name'),'best_reference_labels':best.get('reference_labels'),'reference_sources':best.get('reference_sources'),'identity_pct':best.get('identity_pct'),'query_coverage_pct':best.get('query_coverage_pct'),'subject_coverage_pct':best.get('subject_coverage_pct'),'evalue':best.get('evalue'),'strict_reference_support':bool(r['strict_hits'])})
for e,r in zip(export,rows):
    e['strict_reference_classes']=';'.join(r['strict_reference_classes'])
    e['model_reference_review_required']=r['reference_review']
    e['reference_review_reason']=r['reference_review_reason']
pd.DataFrame(export).to_csv(out/'PREDICTIONS_WITH_REFERENCE.tsv',sep='\t',index=False)
payload=json.dumps(rows,ensure_ascii=False,allow_nan=False).replace('<','\\u003c')
