lines=['SpaceM predictions and reference evidence','',f'{len(h)} proteins: ARG {sum(h.final_class=="ARG")}, MRG {sum(h.final_class=="MRG")}, MGE {sum(h.final_class=="MGE")}, OTHER {sum(h.final_class=="OTHER")}. Mobility scores use full genomic contexts.','']
